Expression:
COALESCE(CALCULATE(
    DISTINCTCOUNT(ERR[Ambulance Base Location]),
    FILTER(
        VALUES(ERR[Ambulance Base Location]),
        CALCULATE(
            MAX(ERR[MDT Used Flag])
        ) = 1
    )
), 0)

CALCULATE(
    DISTINCTCOUNT(ERR[Ambulance Base Location]),
    FILTER(
        VALUES(ERR[Ambulance Base Location]),
        CALCULATE(
            MAX(ERR[MDT Used Flag]),
            REMOVEFILTERS(ERR[District Name])
        ) = 0
    ), ERR[Ambulance Base Location]<>"null", ERR[Ambulance Base Location]<>"Backup"
)

var selectedLocality = SELECTEDVALUE(Locality[Locality])
var avg_art_sec = CALCULATE(AVERAGE(ERR[ART secs.]), ERR[ART Eligible] = "Yes", ERR[ART secs.] > 0, ERR[ART secs.] < 6000)

RETURN 
    IF(
        ISBLANK(avg_art_sec), "#00000000",
        SWITCH(
            TRUE(),
            avg_art_sec > 1080 && selectedLocality = "Urban", "#E53935",
            avg_art_sec > 1380 && selectedLocality = "Rural", "#E53935",
            avg_art_sec > 1980 && selectedLocality = "Tribal", "#E53935",
            "#1DB954"
        )
    )

CALCULATE(
    DIVIDE(
        CALCULATE(SUM(ERR[Abandoned After Dispatch]), ERR[MDT Abandoned Reason new] IN {"Address not clear", "Vehicle Breakdown", "Scene Safety (Mob/Drunken/Riots/Blast)", "EMT/Pilot Sick", "Patient willing to goto hospital", "null", "Bad road condition"}),
        CALCULATE(
            COUNTROWS(
                FILTER(ERR, NOT ISBLANK(ERR[Assign Time]))
            ),
            ALL(ERR[MDT Abandoned Reason new])
        )
    ),
    ERR[Ambulance Base Location] <> "Backup"
)

var segment = SELECTEDVALUE(Segments[Base Location])
var selectedLocality = CALCULATE(MAX(Segments[Locality]), Segments[Base Location] = segment)
var ART_min = AVERAGE(ERR[ART mins.])

RETURN 
IF(ISBLANK(ART_min), "#00000000",
SWITCH(
    TRUE(),
    ISBLANK(segment), "#070F25",
    ART_min > 18 && selectedLocality = "Urban", "#E91D26",
    ART_min > 23 && selectedLocality = "Rural", "#E91D26",
    ART_min > 33 && selectedLocality = "Tribal", "#E91D26",
    "#46B648"
))

var vehicle = SELECTEDVALUE('Vehicles Master Database'[Vehicle Number])
var selectedLocality = CALCULATE(MAX('Vehicles Master Database'[Locality]), 'Vehicles Master Database'[Vehicle Number] = vehicle)
var ART_min = AVERAGE(ERR[ART mins.])

RETURN 
IF(ISBLANK(ART_min), "#00000000",
SWITCH(
    TRUE(),
    ISBLANK(vehicle), "#070F25",
    ART_min > 18 && selectedLocality = "Urban", "#E91D26",
    ART_min > 23 && selectedLocality = "Rural", "#E91D26",
    ART_min > 33 && selectedLocality = "Tribal", "#E91D26",
    "#46B648"
))

CALCULATE(
    DISTINCTCOUNT(ERR[Event Id]), 
    ERR[Accept Time Bin] IN {"2-3 min", "3-4 min", "4-5 min", ">5 min"}
)

CALCULATE(
    DISTINCTCOUNT(ERR[Event Id]),
    ERR[On Action Time Bin] IN {"2-3 min", "3-4 min", "4-5 min", ">5 min"}
)

CALCULATE(
    DISTINCTCOUNT(ERR[Event Id]),
    ERR[Hospital To Hospital Transfer] = FALSE(),
    ERR[Enroute Time Bin] IN {"10-11 min", "11-12 min", "12-13 min", "13-14 min", "14-15 min", ">15 min"}
)

IF(
    SELECTEDVALUE('Vehicles Master Database'[Base Location]) IN ALLSELECTED(Segments[Base Location]), 1, 0
)
